fp_is <- function(cfg)identical(cfg$research_family,"flexible_interval_prediction")
fp_scenarios <- function(cfg)data.frame(label="冻结记录预测",SCENARIO=1L)
fp_catalog <- c(exponential="指数",weibull="Weibull",gengamma="广义Gamma Prentice",loghaz_spline="自然样条log风险+恒定尾部",rp_hazard="Royston-Parmar log累计风险",ispline_hazard="正系数I-spline累计风险")
fp_valid_model <- function(m){if(m$id %in% c("rp_hazard","ispline_hazard"))return(fs_valid(m));if(m$id %in% c("exponential","weibull","pwe"))return(ms_valid_model(m));if(m$id=="gengamma")return(length(m$params)==3&&all(is.finite(m$params))&&m$params[2]>0&&abs(m$params[3])<=10);if(m$id=="loghaz_spline")return(length(m$params)==length(m$knots)+2&&all(is.finite(m$params))&&all(is.finite(m$knots)&m$knots>0)&&!is.unsorted(m$knots,strictly=TRUE)&&is.finite(m$tail)&&m$tail>max(c(0,m$knots))&&m$time_scale>0);if(m$id=="blinded_ph")return(fp_valid_model(m$baseline)&&m$allocation>0&&m$allocation<1&&m$hr>0&&is.finite(m$hr));if(m$id=="predictive_mixture")return(length(m$models)==length(m$weights)&&all(m$weights>=0)&&abs(sum(m$weights)-1)<1e-8&&all(vapply(m$models,fp_valid_model,logical(1))));FALSE}
validate_flexible_prediction <- function(cfg){if(!cfg$uncertainty %in% c("plugin","bootstrap"))stop("参数处理仅plugin或患者Bootstrap。");if(!fp_is(cfg)||!cfg$purpose %in% c("fit","counts","target")||!cfg$analysis_mode %in% c("pooled","grouped","blinded")||!cfg$source %in% c("parameters","data")||!cfg$gap_mode %in% c("strict","complete"))stop("选择模型/预测需求、组别处理及输入来源。")
  d<-if(cfg$source=="parameters"&&!nrow(cfg$data))cfg$data else fx_interval_data(cfg$data,cfg$cut,blinded=cfg$analysis_mode!="grouped");if(cfg$analysis_mode=="blinded"&&(!is.finite(cfg$allocation)||cfg$allocation<=0||cfg$allocation>=1||!is.finite(cfg$assumed_hr)||cfg$assumed_hr<.01||cfg$assumed_hr>10))stop("盲态分配概率(0,1)，外部假设HR0.01–10；不从盲态资料估计HR。")
  if(cfg$source=="data"){if(!length(cfg$candidates)||any(!cfg$candidates %in% names(fp_catalog))||anyDuplicated(cfg$candidates)||!cfg$combination %in% c("single","aic","stacking"))stop("候选模型与组合方式不符。");if(cfg$combination=="single"&&length(cfg$candidates)!=1)stop("预定单模型只选一项。");if(cfg$combination=="stacking"&&(!cfg$folds %in% 2:5))stop("stacking折数2–5。");if(any(c("loghaz_spline","rp_hazard","ispline_hazard") %in% cfg$candidates)&&(!is.numeric(cfg$knots)||any(!is.finite(cfg$knots)|cfg$knots<=0)||is.unsorted(cfg$knots,strictly=TRUE)||length(cfg$knots)>6||!is.finite(cfg$tail)||cfg$tail<=max(c(0,cfg$knots))||!is.finite(cfg$time_scale)||cfg$time_scale<=0))stop("样条0–6正递增切点；上边界/恒定尾起点须超过全部切点；时间尺度正。")}
  if(cfg$source=="data"&&"rp_hazard" %in% cfg$candidates&&(length(cfg$rp_lower)!=1L||!is.finite(cfg$rp_lower)||cfg$rp_lower<=0||cfg$rp_lower>=min(c(cfg$knots,cfg$tail))))stop("RP下边界正且小于全部内部切点/上边界。");
  if(cfg$source=="parameters"&&!fp_valid_model(cfg$parameter_model))stop("指定模型参数不完整。")
  if(!is.finite(cfg$seed)||cfg$seed<0||cfg$seed>.Machine$integer.max||cfg$seed!=floor(cfg$seed))stop("种子为非负整数。")
  if(!length(cfg$reference_ages)||length(cfg$reference_ages)>50||any(!is.finite(cfg$reference_ages)|cfg$reference_ages<=0)||is.unsorted(cfg$reference_ages,strictly=TRUE))stop("模型参考年龄1–50个正递增值。")
  if(cfg$purpose!="fit"){
    if(cfg$reps<20||cfg$reps>10000||cfg$reps!=floor(cfg$reps)||cfg$max_day<=cfg$cut||cfg$max_day>3650||cfg$new_n<0||cfg$new_n!=floor(cfg$new_n)||nrow(d)+cfg$new_n>5000||(cfg$new_n>0&&cfg$enroll_rate<=0)||any(!is.finite(cfg$dropout_rates)|cfg$dropout_rates<0)||!setequal(names(cfg$group_weights),names(cfg$dropout_rates))||any(cfg$group_weights<=0)||!all(d$TRTP %in% names(cfg$group_weights)))stop("预测B20–10000，IA之后窗口≤3650日，旧加新≤5000；组权重正，退出率非负，新入组率正。")
    if(nrow(d)+cfg$new_n<1)stop("预测至少需要一名已有或未来患者。");
    if(cfg$gap_mode=="strict"&&any(d$EXIT=="active"&abs(d$ENTRY+d$L-cfg$cut)>1e-7))stop("仍随访未确认至IA：选择模型补全确认间隙，或先提供当前确认记录；不把缺失更新自动当作无事件。")
    if(cfg$purpose=="counts"&&(length(cfg$horizons)<1||length(cfg$horizons)>20||any(!is.finite(cfg$horizons)|cfg$horizons<=cfg$cut|cfg$horizons>cfg$max_day)||is.unsorted(cfg$horizons,strictly=TRUE)))stop("未来截点1–20个，正递增、IA之后且窗口内。")
    if(cfg$purpose=="target"&&(!is.finite(cfg$target)||cfg$target<1||cfg$target!=floor(cfg$target)))stop("事件目标为正整数。")
    if((nrow(d)+cfg$new_n)*cfg$reps>2e7)stop("最多2000万患者×轮次。")
  }
  invisible(TRUE)
}
fp_prepare <- function(state){if(!is.null(state$prepared))return(state);cfg<-state$config;groups<-if(cfg$source=="parameters")"Combined" else if(cfg$purpose=="fit")unique(cfg$data$TRTP) else names(cfg$group_weights)
  state$prepared<-batch_with_rng(cfg$seed,{fits<-setNames(lapply(groups,function(g){if(cfg$source=="parameters")list(model=fx_wrap_blind(cfg$parameter_model,cfg),candidates=list(specified=cfg$parameter_model),weights=c(specified=1),failures=list(),fold_records=data.frame()) else fx_fit_group(cfg$data[cfg$data$TRTP==g,,drop=FALSE],cfg)}),groups);list(fits=fits,data_hash=batch_config_hash(list(data=cfg$data)))});state}
fp_model_overview <- function(p)batch_bind_columns(lapply(names(p$fits),function(g){x<-p$fits[[g]];ok<-batch_bind_columns(lapply(names(x$candidates),function(k){m<-x$candidates[[k]];base<-if(m$id=="blinded_ph")m$baseline else m;data.frame(group=g,candidate=k,accepted=TRUE,weight=unname(x$weights[k]),loglik=m$loglik %||% NA_real_,aic=m$aic %||% NA_real_,parameters=paste(signif(base$params,7),collapse=","),note="参数采用内部连续日；盲态HR与分配比例是外部假设。") }));bad<-batch_bind_columns(lapply(names(x$failures),function(k)data.frame(group=g,candidate=k,accepted=FALSE,weight=NA_real_,loglik=NA_real_,aic=NA_real_,parameters="",note=x$failures[[k]])));batch_bind_columns(list(ok,bad))}))
fp_reference <- function(p,cfg){batch_bind_columns(lapply(names(p$fits),function(g){m<-p$fits[[g]]$model;t<-cfg$reference_ages;S<-model_survival(m,t);d<-data.frame(group=g,age_day=t,survival=S,hazard_per_day=exp(fx_density_any(m,t)+model_cumhaz(m,t)),median_day=inverse_cumhaz(m,log(2)))
  if(cfg$analysis_mode=="blinded"){parts<-if(m$id=="predictive_mixture")m$models else list(m);w<-if(m$id=="predictive_mixture")m$weights else 1;num<-Reduce(`+`,lapply(seq_along(parts),function(j)w[j]*parts[[j]]$allocation*exp(-parts[[j]]$hr*model_cumhaz(parts[[j]]$baseline,t))));d$treatment_probability_given_survival<-num/S}
  d}))}
fp_sample_interval <- function(m,L,R){a<--model_cumhaz(m,L);b<--model_cumhaz(m,R);v<-a+log1p(-runif(1)*(-expm1(b-a)));inverse_cumhaz(m,-v)}
fp_truth <- function(d,prepared,cfg,b){old<-batch_bind_columns(lapply(seq_len(nrow(d)),function(i){x<-d[i,];m<-prepared$fits[[x$TRTP]]$model;e<-if(x$TYPE=="exact")x$R else if(x$TYPE %in% c("left","interval"))fp_sample_interval(m,x$L,x$R) else sample_conditional(m,x$L);drop<-if(x$EXIT=="dropout")x$L else if(x$EXIT=="event")Inf else {mu<-cfg$dropout_rates[[x$TRTP]];if(mu>0)cfg$cut-x$ENTRY+rexp(1,mu) else Inf}
    data.frame(SIMID=b,USUBJID=x$USUBJID,group=x$TRTP,entry_day=x$ENTRY,event_time_day=e,event_day=x$ENTRY+e,dropout_time_day=drop,dropout_day=x$ENTRY+drop,observed_IA_event=x$EXIT=="event",source="frozen_IA") }))
  if(!nrow(old))old<-data.frame(SIMID=integer(),USUBJID=character(),group=character(),entry_day=numeric(),event_time_day=numeric(),event_day=numeric(),dropout_time_day=numeric(),dropout_day=numeric(),observed_IA_event=logical(),source=character())
  if(cfg$new_n>0){entry<-cfg$cut+cumsum(rexp(cfg$new_n,cfg$enroll_rate));g<-sample(names(cfg$group_weights),cfg$new_n,replace=TRUE,prob=cfg$group_weights);new<-batch_bind_columns(lapply(seq_len(cfg$new_n),function(i){m<-prepared$fits[[g[i]]]$model;e<-sample_conditional(m,0);mu<-cfg$dropout_rates[[g[i]]];dr<-if(mu>0)rexp(1,mu) else Inf;data.frame(SIMID=b,USUBJID=paste0("FUTURE_",b,"_",i),group=g[i],entry_day=entry[i],event_time_day=e,event_day=entry[i]+e,dropout_time_day=dr,dropout_day=entry[i]+dr,observed_IA_event=FALSE,source="future_entry")}));old<-batch_bind_columns(list(old,new))};old}
fp_trial <- function(cfg,sc,b,prepared,keep_sample=FALSE)batch_with_rng(batch_replicate_seed(cfg$seed,1L,b),{tryCatch({p<-prepared
  if(cfg$uncertainty=="bootstrap"&&cfg$source=="data"){boot<-batch_bind_columns(lapply(split(cfg$data,cfg$data$TRTP),function(x)x[sample(seq_len(nrow(x)),replace=TRUE),,drop=FALSE]));boot$USUBJID<-paste0("BOOT_",seq_len(nrow(boot)));c<-cfg;c$data<-boot;c$seed<-batch_replicate_seed(cfg$seed,1L,b);p<-fp_prepare(list(config=c))$prepared}
  tr<-fp_truth(cfg$data,p,cfg,b);e<-tr$event_day[is.finite(tr$event_day)&tr$event_time_day<=tr$dropout_time_day];known<-sum(cfg$data$EXIT=="event");pending<-sum(e<=cfg$cut)-known;day<-cfg$max_day;reached<-NA
  if(cfg$purpose=="target"){e<-sort(e);t<-if(length(e)>=cfg$target)e[cfg$target] else Inf;reached<-t<=cfg$max_day;day<-if(reached)max(cfg$cut,t) else cfg$max_day}
  h<-if(cfg$purpose=="counts")cfg$horizons else day;draws<-batch_bind_columns(lapply(h,function(t)data.frame(SCENARIO=1L,SIMID=b,DCO_DAY=t,known_IA_events=known,model_pending_IA_events=pending,incident_after_IA=sum(e>cfg$cut&e<=t),model_cumulative_events=sum(e<=t),confirmed_IA_plus_future=known+sum(e>cfg$cut&e<=t))))
  row<-data.frame(SCENARIO=1L,SIMID=b,replicate_seed=batch_replicate_seed(cfg$seed,1L,b),generated=TRUE,decision_valid=cfg$purpose=="target",decision_reject=reached,note="")
  mr<-data.frame(SCENARIO=1L,SIMID=b,method="prediction",generated=TRUE,decision_valid=cfg$purpose=="target",decision_reject=reached,target_reached=reached,final_day=day,wait_day=day-cfg$cut,n_observed=sum(tr$entry_day<day),events=sum(e<=day),future_analysis_count=0L,action=if(cfg$purpose=="counts")"count_window" else if(reached)"target" else "window")
  out<-list(row=row,method_rows=mr,draw_rows=draws,looks=data.frame());if(keep_sample){out$truth<-tr;out$observed<-survival_at_cut(tr,day,1L);out$observed$PARAMCD<-cfg$paramcd;out$frozen_intervals<-cfg$data;out$study_config<-list(origin=cfg$origin,display_unit="days",paramcd=cfg$paramcd)};out
  },error=function(e)list(row=data.frame(SCENARIO=1L,SIMID=b,replicate_seed=batch_replicate_seed(cfg$seed,1L,b),generated=FALSE,decision_valid=FALSE,decision_reject=NA,note=conditionMessage(e)),method_rows=data.frame(SCENARIO=1L,SIMID=b,method="prediction",generated=FALSE,decision_valid=FALSE,decision_reject=NA,target_reached=NA),looks=data.frame(),draw_rows=data.frame()))})
fp_aggregate <- function(state){state<-research_aggregate(state,"prediction",c(prediction="柔性/盲态条件预测"));p<-state$prepared;cfg<-state$config;state$model_overview<-if(is.null(p))data.frame() else fp_model_overview(p);state$model_reference<-if(is.null(p))data.frame() else fp_reference(p,cfg);state$fold_records<-if(is.null(p))data.frame() else batch_bind_columns(lapply(names(p$fits),function(g){d<-p$fits[[g]]$fold_records;if(nrow(d))d$group<-g;d}));d<-state$draw_rows
  state$count_overview<-if(nrow(d))batch_bind_columns(lapply(split(d,d$DCO_DAY),function(x)batch_bind_columns(lapply(c("known_IA_events","model_pending_IA_events","incident_after_IA","model_cumulative_events","confirmed_IA_plus_future"),function(k){q<-as.numeric(quantile(x[[k]],c(.025,.5,.975)));data.frame(DCO_DAY=x$DCO_DAY[1],metric=k,requested=cfg$reps,valid=nrow(x),mean=mean(x[[k]]),lower=q[1],median=q[2],upper=q[3])})))) else data.frame()
  state$target_overview<-if(cfg$purpose=="target"){v<-state$method_rows$target_reached;days<-state$method_rows$final_day[v %in% TRUE];q<-if(length(days))as.numeric(quantile(days,c(.025,.5,.975))) else rep(NA_real_,3);cbind(data.frame(target=cfg$target,finite_dates=length(days),target_lower_day=q[1],target_median_day=q[2],target_upper_day=q[3]),jr_probability(v,cfg$reps))} else data.frame();state}
fp_fit_only <- function(cfg){validate_flexible_prediction(cfg);fp_aggregate(fp_prepare(research_initial(cfg,fp_scenarios(cfg),function(s)s)))}
run_flexible_prediction <- function(cfg,progress=function(state)NULL,should_cancel=function()FALSE,replay_keys=NULL,resume_state=NULL,continuation_operation="resume"){validate_flexible_prediction(cfg);if(cfg$purpose=="fit")stop("模型拟合无需后台预测研究。");research_family_run(cfg,fp_scenarios(cfg),fp_trial,fp_aggregate,progress,should_cancel,replay_keys,resume_state,continuation_operation,fp_prepare)}
fp_initial <- function(cfg,initial=NULL)research_initial(cfg,fp_scenarios(cfg),fp_aggregate,initial)
fp_sample <- function(r,scenario,replicate){if(!any(r$rows$SIMID==replicate&r$rows$generated))stop("请选择已生成轮次。");fp_trial(r$config,r$scenarios[1,,drop=FALSE],replicate,r$prepared,TRUE)}
fp_report <- function(r)c("# 柔性、区间与盲态模型开发稿",paste0("版本",r$version,"；",r$config$purpose,"；处理",r$completed,"/",r$total),capture.output(print(r$model_overview,row.names=FALSE)),capture.output(print(r$model_reference,row.names=FALSE)),capture.output(print(r$count_overview,row.names=FALSE)),capture.output(print(r$target_overview,row.names=FALSE)),"盲态PH使用外部给定HR与分配比例，不识别真实治疗效应。log风险样条、RP log累计风险及正系数I-spline分别定义；RP逐片段导数与两尾约束，I-spline正线性尾保证proper分布。确认间隙的模型补全事件不是已报告事件。独立/可忽略删失观察假设必须适用；实际迟报及信息性退出不自动修正。未运行验证。")
fp_validate_saved <- function(state,cfg){p<-state$prepared;if(is.null(p))return(invisible(TRUE));if(!identical(p$data_hash,batch_config_hash(list(data=cfg$data))))stop("保存柔性模型与冻结输入不符。");if(any(!vapply(p$fits,function(x)fp_valid_model(x$model),logical(1))))stop("保存柔性模型结构不完整。");invisible(TRUE)}
